import {useState, useEffect} from 'react'
import {Button} from '@primer/react'
import {SquareFillIcon} from '@primer/octicons-react'
import {SessionState} from '../types/session'
import {useSessionContext} from '../contexts/SessionContext'
import {useCAPIQuery} from '../hooks/useCAPIQuery'
import {fetchCAPI} from '../utils/fetch-capi'

export function SessionStopButton({nwo, currentUserCanPush}: {nwo: string | undefined; currentUserCanPush: boolean}) {
  const {session} = useSessionContext()

  const [isSessionStopped, setIsSessionStopped] = useState(false)
  const stoppableStates: string[] = [SessionState.InProgress, SessionState.Idle, SessionState.WaitingForUser]
  const sessionStoppable = stoppableStates.includes(session.state) && !isSessionStopped

  const stopSessionQuery = useCAPIQuery({
    queryKey: ['stopSession', nwo, session.id],
    queryFn: async () => {
      const response = await fetchCAPI({
        path: `/agents/swe/jobs/${nwo}/session/${session.id}/cancel`,
        method: 'POST',
      })
      return response
    },
    enabled: false,
    retry: false,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
  })

  // Listen for query success state
  useEffect(() => {
    if (stopSessionQuery.isSuccess && !stopSessionQuery.isLoading) {
      setIsSessionStopped(true)
    }
  }, [stopSessionQuery.isSuccess, stopSessionQuery.isLoading])

  const stoppingSession = stopSessionQuery.isFetching || stopSessionQuery.isLoading
  const buttonText = stoppingSession ? 'Stopping session...' : 'Stop session'

  // No button if the user lacks permission or the session is not stoppable
  if (!nwo || !currentUserCanPush || !sessionStoppable) return null

  return (
    <Button
      className="mr-2"
      leadingVisual={SquareFillIcon}
      variant="danger"
      onClick={() => stopSessionQuery.refetch()}
      loading={stoppingSession}
      loadingAnnouncement="Stopping session"
      aria-disabled={stoppingSession}
    >
      {buttonText}
    </Button>
  )
}

try{ SessionStopButton.displayName ||= 'SessionStopButton' } catch {}