import styles from './UserCommand.module.css'
import {AlertIcon} from '@primer/octicons-react'

interface UserCommandProps {
  content: string
  state: 'queued' | 'in_progress' | 'failed' | 'completed' | 'dismissed'
  timestamp?: string
}

// Replace class-based descriptors with a simple mapping for clarity and brevity.
const DESCRIPTORS: Record<
  UserCommandProps['state'],
  {actionText: string; postScript?: string; containerStateClass?: string}
> = {
  queued: {actionText: 'queued a comment', containerStateClass: styles.containerMuted},
  failed: {
    actionText: 'queued a comment',
    postScript: 'There was an error sending the message',
    containerStateClass: styles.containerMuted,
  },
  in_progress: {actionText: 'commented'},
  completed: {actionText: 'commented'},
  dismissed: {
    actionText: 'commented (dismissed)',
    postScript: 'Session completed before the agent could pick up this comment',
    containerStateClass: styles.containerMuted,
  },
}

function stateToDescriptors(state: UserCommandProps['state']) {
  return DESCRIPTORS[state]
}

export function UserCommand({content, state}: UserCommandProps) {
  const displayName = 'user'
  const descriptors = stateToDescriptors(state)
  const actionText = descriptors.actionText
  const postScript = descriptors.postScript
  const containerStateClass = descriptors.containerStateClass

  return (
    <div className={`${styles.commandContainer} ${containerStateClass ?? ''}`}>
      <div className={`mb-1`}>
        <span className={styles.username}>{displayName}</span> {actionText}
      </div>
      <div className={`p-2 color-shadow-small ${styles.commandBox}`}>{content}</div>
      {postScript && (
        <div>
          <AlertIcon /> {postScript}
        </div>
      )}
    </div>
  )
}

try{ UserCommand.displayName ||= 'UserCommand' } catch {}