import {useCAPIQuery} from './useCAPIQuery'
import type {CommandsResponse} from '../types/session'
import {useSessionContext} from '../contexts/SessionContext'
import {fetchCAPI} from '../utils/fetch-capi'

export interface UseListCommandsProps {
  pollingInterval: number
}

export function useListCommands({pollingInterval}: UseListCommandsProps) {
  const {session} = useSessionContext()
  const activeSessionId = session.id

  const query = useCAPIQuery<CommandsResponse>({
    queryKey: ['agent-session-commands', activeSessionId],
    queryFn: async () => {
      const result = await fetchCAPI({
        path: `/agents/sessions/${activeSessionId}/commands?sort=created_at,asc`,
        method: 'GET',
      })

      if (!result.ok) {
        throw new Error(`Failed to fetch commands: ${result.statusText}`)
      }

      return result.json() as Promise<CommandsResponse>
    },
    refetchInterval: () => {
      if (session.state === 'in_progress' || session.state === 'queued') {
        return pollingInterval
      }
      return false
    },
  })

  return {
    data: query.data?.commands ?? [],
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error,
  }
}
