const USER_ROLE: MessageRole = 'user'
const ASSISTANT_ROLE: MessageRole = 'assistant'

interface SessionContentProps extends UseSessionLogsProps {
  showCopilotCodingAgentPremiumRequestsBanner: boolean
}

export function SessionContent({
  logsPollingInterval,
  showCopilotCodingAgentPremiumRequestsBanner,
}: SessionContentProps) {
  return (
    <div>
      <SessionHeader />
      <Stack direction="vertical" padding={'spacious'} className={'border border-top-0 bgColor-inset rounded-bottom-2'}>
        <PremiumRequestsBanner enabled={showCopilotCodingAgentPremiumRequestsBanner} />
        <SessionLogs logsPollingInterval={logsPollingInterval} />
      </Stack>
    </div>
  )
}

function SessionHeader() {
  const {
    session: {
      state,
      created_at: createdAt,
      completed_at: completedAt,
      workflow_run_id,
      premium_requests: premiumRequests,
    },
  } = useSessionContext()
  const {ownerLogin, name: repoName, currentUserCanPush} = useCurrentRepository()
  const premiumRequestsEnabled = useFeatureFlag('copilot_coding_agent_premium_requests')

  const nwo = `${ownerLogin}/${repoName}`
  const workflowLink = generateWorkflowRunLink(nwo, workflow_run_id)

  return (
    <div className="position-sm-sticky top-0 pt-2 bgColor-default" style={{zIndex: 1}}>
      <Stack
        direction={'horizontal'}
        gap={'spacious'}
        wrap="wrap"
        className={'px-4 py-3 border rounded-2 rounded-bottom-0'}
      >
        <Stack gap="condensed">
          <span className="text-small fgColor-muted">Status</span>
          <span className="h4 text-semibold">{getReadableSessionState(state)}</span>
        </Stack>
        {state !== 'queued' && (
          <Stack gap="condensed">
            <span className="text-small fgColor-muted">Duration</span>
            <span role="timer" className="text-semibold h4">
              <SessionElapsedTime createdAt={createdAt} completedAt={completedAt} state={state} />
            </span>
          </Stack>
        )}
        {state !== 'queued' && premiumRequestsEnabled && (
          <Stack gap="condensed">
            <span className="text-small fgColor-muted">Premium requests</span>
            <Stack direction="horizontal">
              <span className="h4 text-semibold">{premiumRequests}</span>
              <Tooltip text="Learn more about premium requests">
                <Link
                  href="https://docs.github.com/copilot/managing-copilot/monitoring-usage-and-entitlements/about-premium-requests"
                  aria-label="Learn more about premium requests"
                  inline
                  muted
                >
                  <InfoIcon className="v-align-middle" aria-hidden="true" />
                </Link>
              </Tooltip>
            </Stack>
          </Stack>
        )}
        {workflowLink && (
          <div className="flex-1 d-flex flex-justify-end">
            <SessionStopButton nwo={nwo} currentUserCanPush={currentUserCanPush} />
            <ActionMenu>
              <ActionMenu.Anchor>
                <IconButton icon={KebabHorizontalIcon} aria-label="Open menu" />
              </ActionMenu.Anchor>
              <ActionMenu.Overlay>
                <ActionList>
                  <ActionList.LinkItem href={workflowLink}>View verbose logs</ActionList.LinkItem>
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          </div>
        )}
      </Stack>
    </div>
  )
}

export function SessionLogs({logsPollingInterval}: {logsPollingInterval: number}) {
  const {session} = useSessionContext()
  const {ownerLogin, name: repoName} = useCurrentRepository()
  const currentUser = useCurrentUser()
  const currentUserOwnsSession = currentUser?.id === session.user_id

  const isSessionCommandsEnabled = isFeatureEnabled('sessions_steering_commands')

  const {data: commandsData} = useListCommands({
    pollingInterval: logsPollingInterval, // Use same interval as logs
  })

  const handleSteeringCommandSubmit = async (message: string) => {
    try {
      const response = await fetchCAPI({
        path: `/agents/sessions/${session.id}/commands`,
        method: 'POST',
        body: {content: message},
      })
      if (!response.ok) {
        throw new Error(`Failed to post comment: ${response.statusText}`)
      }
    } catch {
      // Silently handle errors for now
    }
  }

  const {
    data: logsData,
    isLoading: logsIsLoading,
    showPollingError,
  } = useLogs({
    logsPollingInterval,
  })
  useSyncFavicon(session.state)

  const dedupedCompletionChunks = useMemo(() => {
    const completionChunks = (logsData ?? []).filter(isCompletionChunk)
    return dedupeCompletionChunks(completionChunks)
  }, [logsData])

  // Return early if in the queued state
  if (session.state === 'queued') {
    return (
      <Blankslate>
        <Blankslate.Visual>
          <ClockIcon size={32} />
        </Blankslate.Visual>
        <Blankslate.Heading>Waiting to start</Blankslate.Heading>
        <Blankslate.Description>Copilot has queued work on this session, waiting to start...</Blankslate.Description>
      </Blankslate>
    )
  }

  return (
    <>
      {logsIsLoading && !showPollingError && <LoadingMessage message="Loading…" />}
      {!logsIsLoading && !showPollingError && logsData?.length === 0 && session.state !== 'in_progress' && (
        <div>No logs to display</div>
      )}
      {!logsIsLoading && logsData && logsData?.length > 0 && (
        <>
          {dedupedCompletionChunks.map(entry => {
            return <LogEntry key={`entry-${entry.id}`} {...entry} />
          })}
          {/* Render pending/failed commands */}
          {isSessionCommandsEnabled && commandsData?.length > 0 && (
            <>
              {commandsData.map(command => (
                <UserCommand key={`command-${command.id}`} content={command.content} state={command.state} />
              ))}
            </>
          )}
        </>
      )}
      {showPollingError && (
        <Banner
          title="Error"
          hideTitle
          description="There was an error loading the logs. Please try again later."
          variant="critical"
          primaryAction={(() => {
            const workflowLink = session.workflow_run_id
              ? generateWorkflowRunLink(`${ownerLogin}/${repoName}`, session.workflow_run_id)
              : undefined

            return workflowLink ? (
              <Banner.PrimaryAction as="a" href={workflowLink}>
                View detailed logs
              </Banner.PrimaryAction>
            ) : undefined
          })()}
        />
      )}
      {session.state === 'in_progress' && !logsIsLoading && !showPollingError && (
        <>
          {logsData && logsData.length > 0 ? <LoadingMessage message="Copilot is working…" /> : <BootingUpMessage />}
          {isSessionCommandsEnabled && currentUserOwnsSession && (
            <StickySteeringCommand onSubmit={handleSteeringCommandSubmit} />
          )}
        </>
      )}
      {session.state === 'failed' && !showPollingError && (
        <SessionFailedBanner errorMessage={session.error?.message ?? null} workflowRunId={session.workflow_run_id} />
      )}
    </>
  )
}

interface LogEntryProps extends CompletionChunk {}

function LogEntry({choices}: LogEntryProps) {
  return (
    <>
      {choices.map((choice, i) => (
        // eslint-disable-next-line @eslint-react/no-array-index-key
        <LogEntryChoice key={`choice-${i}`} choice={choice} />
      ))}
    </>
  )
}

type LogEntryChoiceProps = {
  choice: Choice
}

function LogEntryChoice({choice}: LogEntryChoiceProps) {
  const tool = choice.delta.tool_calls?.[0]

  if (!tool && choice.delta.content && choice.delta.role === USER_ROLE) {
    return <UserCommand content={choice.delta.content} state="completed" />
  }
  if (!tool && choice.delta.content && choice.delta.role === ASSISTANT_ROLE) {
    return <CopilotMessage content={choice.delta.content} />
  }

  const toolFunction = tool?.function
  if (!tool || !tool.id || !toolFunction) {
    return null
  }

  let component = null

  try {
    component = (
      <ToolRenderer
        name={toolFunction.name}
        delta={choice.delta}
        // Defensively replace newlines that may appear in JSON to avoid possible parsing errors
        // This may not be needed if the backend is already handling this correctly, but better safe than sorry
        args={JSON.parse(toolFunction.arguments.replace(/\n/g, '\\n'))}
      />
    )
  } catch {
    component = (
      <Tool title={'Error parsing tool call arguments'} isError>
        <ToolPrimaryContent language={'text'} markdown={toolFunction.arguments} />
      </Tool>
    )
  }

  if (choice.delta.reasoning_text) {
    return (
      <>
        <ReasoningText content={choice.delta.reasoning_text} />
        {component}
      </>
    )
  }

  return component
}

function CopilotMessage({content}: {content: string}) {
  const isStripEnabled = useFeatureFlag('logs_pr_tag_strip')
  if (isStripEnabled) {
    content = content.replace(/<pr_title>.*?<\/pr_title>|<pr_description>.*?<\/pr_description>/gs, '')
  }
  return <MarkdownRenderer markdown={content} />
}

function ReasoningText({content}: {content: string}) {
  return <MarkdownRenderer markdown={content} />
}

try{ SessionContent.displayName ||= 'SessionContent' } catch {}
try{ SessionHeader.displayName ||= 'SessionHeader' } catch {}
